55	/**
56	 * @author Vitaliy Fedoriv
57	 */
58	
59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    /** Dedicated audit trail for owner-lifecycle side effects. */
65	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
66	
67	    private final ClinicService clinicService;
68	
69	    private final OwnerMapper ownerMapper;
70	
71	    private final PetMapper petMapper;
72	
73	    private final VisitMapper visitMapper;
74	
75	    public OwnerRestControllerV1(ClinicService clinicService,
76	                                 OwnerMapper ownerMapper,
77	                                 PetMapper petMapper,
78	                                 VisitMapper visitMapper) {
79	        this.clinicService = clinicService;
80	        this.ownerMapper = ownerMapper;
81	        this.petMapper = petMapper;
82	        this.visitMapper = visitMapper;
83	    }
84	
85	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
86	    @Override
87	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
88	        Collection<Owner> owners;
89	        if (lastName != null) {
90	            owners = this.clinicService.findOwnerByLastName(lastName);
91	        } else {
92	            owners = this.clinicService.findAllOwners();
93	        }
94	        if (owners.isEmpty()) {
95	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
96	        }
97	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
98	    }
99	
100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
103	        Owner owner = this.clinicService.findOwnerById(ownerId);
104	        if (owner == null) {
105	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
106	        }
107	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
108	    }
109	
110	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
111	    @Override
112	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
113	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
114	        if (normalizedTelephone == null) {
115	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
116	        }
117	        String normalizedAddress = Owner.normalizeAddress(ownerFieldsDto.getAddress());
118	        if (normalizedAddress == null || normalizedAddress.isBlank()) {
119	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
120	        }
121	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
122	        owner.setTelephone(normalizedTelephone);
123	        if (!owner.isPostcodeValidForCity()) {
124	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
125	        }
126	        // Consolidated duplicate detection: all of the former separate telephone, email
127	        // and household checks are now expressed through the single derived identityKey
128	        // (telephone|email|householdId). Reject only when the new owner's WHOLE
129	        // identityKey equals an existing owner's. The household id is assigned later in
130	        // this method, so at this point the new owner's key carries an empty household
131	        // segment; two members of the same household with different telephones therefore
132	        // have different keys and are both allowed.
133	        String identityKey = owner.getIdentityKey();
134	        if (this.clinicService.findAllOwners().stream()
135	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()))) {
136	            return new ResponseEntity<>(HttpStatus.CONFLICT);
137	        }
138	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= 50) {
139	            return new ResponseEntity<>(HttpStatus.CONFLICT);
140	        }
141	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(LocalDate.now())) {
142	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
143	        }
144	        LocalDate effectiveDate =
145	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
146	        LocalDate registrationDate = toBusinessDay(effectiveDate);
147	        long ownersRegisteredToday = countOwnersRegisteredOn(registrationDate);
148	        if (ownersRegisteredToday >= 100) {
149	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
150	        }
151	        boolean bulkSignupWarning = ownersRegisteredToday > 80;
152	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
153	        List<Owner> householdMembers =
154	            findHouseholdMembers(ownerFieldsDto.getLastName(), normalizedAddress);
155	        HttpHeaders headers = new HttpHeaders();
156	        owner.setRegistrationDate(registrationDate);
157	        owner.setCustomerCode(customerCode(owner));
158	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
159	        owner.setBulkSignupWarning(bulkSignupWarning);
160	        // Soft-match ("possible duplicate"): the new owner is not a hard duplicate (its whole
161	        // identityKey is unique) but shares an existing owner's last name and postcode while
162	        // carrying a different telephone. Such an owner is still created, but is flagged so the
163	        // likely duplication can be reviewed, pointing at the matching owner's id.
164	        Owner possibleDuplicate = findPossibleDuplicate(owner);
165	        owner.setPossibleDuplicate(possibleDuplicate != null);
166	        owner.setPossibleDuplicateOf(possibleDuplicate == null ? null : possibleDuplicate.getId());
167	        if (sharesHousehold && !householdMembers.isEmpty()) {
168	            String householdId = householdId(owner.getLastName(), normalizedAddress);
169	            owner.setHouseholdId(householdId);
170	            owner.setHouseholdSize(householdMembers.size() + 1);
171	            for (Owner member : householdMembers) {
172	                if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
173	                    member.setHouseholdId(householdId);
174	                    this.clinicService.saveOwner(member);
175	                }
176	            }
177	        }
178	        this.clinicService.saveOwner(owner);
179	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
180	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
181	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
182	        headers.setLocation(UriComponentsBuilder.newInstance()
183	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
184	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
185	    }
186	
187	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
188	    @Override
189	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
190	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
191	        if (currentOwner == null) {
192	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
193	        }
194	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
195	        if (normalizedTelephone == null) {
196	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
197	        }
198	        currentOwner.setAddress(ownerFieldsDto.getAddress());
199	        currentOwner.setCity(ownerFieldsDto.getCity());
200	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
201	        currentOwner.setLastName(ownerFieldsDto.getLastName());
202	        currentOwner.setTelephone(normalizedTelephone);
203	        currentOwner.setEmail(ownerFieldsDto.getEmail());
204	        this.clinicService.saveOwner(currentOwner);
205	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
206	    }
207	
208	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
209	    @Transactional
210	    @Override
211	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
212	        Owner owner = this.clinicService.findOwnerById(ownerId);
213	        if (owner == null) {
214	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
215	        }
216	        this.clinicService.deleteOwner(owner);
217	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
218	    }
219	
220	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
221	    @Override
222	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
223	        Owner owner = this.clinicService.findOwnerById(ownerId);
224	        if (owner == null) {
225	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
226	        }
227	        HttpHeaders headers = new HttpHeaders();
228	        Pet pet = petMapper.toPet(petFieldsDto);
229	        owner.setId(ownerId);
230	        pet.setOwner(owner);
231	        pet.getType().setName(null);
232	        this.clinicService.savePet(pet);
233	        PetDto petDto = petMapper.toPetDto(pet);
234	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
235	            .buildAndExpand(pet.getId()).toUri());
236	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
237	    }
238	
239	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
240	    @Override
241	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
242	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
243	        if (currentOwner != null) {
244	            Pet currentPet = this.clinicService.findPetById(petId);
245	            if (currentPet != null) {
246	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
247	                currentPet.setName(petFieldsDto.getName());
248	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
249	                this.clinicService.savePet(currentPet);
250	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
251	            }
252	        }
253	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
254	    }
255	
256	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
257	    @Override
258	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
259	        HttpHeaders headers = new HttpHeaders();
260	        Visit visit = visitMapper.toVisit(visitFieldsDto);
261	        Pet pet = new Pet();
262	        pet.setId(petId);
263	        visit.setPet(pet);
264	        this.clinicService.saveVisit(visit);
265	        VisitDto visitDto = visitMapper.toVisitDto(visit);
266	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
267	            .buildAndExpand(visit.getId()).toUri());
268	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
269	    }
270	
271	
272	    /**
273	     * Normalize a telephone number to E.164 form. Spaces, dashes and brackets are
274	     * stripped. When a leading {@code '+'} and country code are present they are kept;
275	     * otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
276	     * is dropped from the national digits. The result must be a {@code '+'} followed
277	     * by 8 to 15 digits, and is returned as {@code +<digits>}; otherwise {@code null}
278	     * is returned to signal a bad request.
279	     */
280	    /**
281	     * Build the customer code for a newly created owner, formatted
282	     * {@code '<REGION>-<HASH8>'} where {@code REGION} is the region derived from the
283	     * owner's postcode (falling back to the city, or {@code 'UNKNOWN'}, via the same
284	     * derivation the locality uses), and {@code HASH8} is the first eight upper-case
285	     * hex characters of the SHA-256 of the owner's normalized telephone concatenated
286	     * with its last name. This identity carries no sequence number.
287	     */
288	    private String customerCode(Owner owner) {
289	        String region = owner.getLocality();
290	        String hash8 = customerCodeHash(owner.getTelephone(), owner.getLastName());
291	        return region + "-" + hash8;
292	    }
293	
294	    /**
295	     * Compute the {@code HASH8} portion of a customer code: the first eight upper-case
296	     * hex characters of the SHA-256 digest of {@code telephone + lastName} (each
297	     * treated as empty when {@code null}), already in their normalized forms.
298	     */
299	    private String customerCodeHash(String telephone, String lastName) {
300	        String key = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
301	        try {
302	            byte[] digest = MessageDigest.getInstance("SHA-256")
303	                .digest(key.getBytes(StandardCharsets.UTF_8));
304	            StringBuilder sb = new StringBuilder();
305	            for (int i = 0; i < 4; i++) {
306	                sb.append(String.format("%02X", digest[i]));
307	            }
308	            return sb.toString();
309	        }
310	        catch (NoSuchAlgorithmException e) {
311	            throw new IllegalStateException(e);
312	        }
313	    }
314	
315	    /**
316	     * Count the existing owners whose city matches the given one, compared after
317	     * collapsing whitespace and lower-casing. Used to enforce the per-city capacity
318	     * cap: a city that already holds this many owners is at capacity.
319	     */
320	    private long countOwnersInCity(String city) {
321	        String normalizedCity = normalizeForHousehold(city);
322	        return this.clinicService.findAllOwners().stream()
323	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(normalizedCity))
324	            .count();
325	    }
326	
327	    /**
328	     * Count the existing owners whose registration date falls on the given day. Used to
329	     * enforce the per-day create limit: once this many owners have been registered today,
330	     * the day is at capacity and further creates are rejected.
331	     */
332	    private long countOwnersRegisteredOn(LocalDate day) {
333	        return this.clinicService.findAllOwners().stream()
334	            .filter(existing -> day.equals(existing.getRegistrationDate()))
335	            .count();
336	    }
337	
338	    /**
339	     * Roll a registration date forward to the next business day: a date falling on a
340	     * Saturday or Sunday is advanced to the following Monday, while a weekday is
341	     * returned unchanged.
342	     */
343	    private LocalDate toBusinessDay(LocalDate date) {
344	        DayOfWeek dayOfWeek = date.getDayOfWeek();
345	        if (dayOfWeek == DayOfWeek.SATURDAY || dayOfWeek == DayOfWeek.SUNDAY) {
346	            return date.plusDays(8 - dayOfWeek.getValue());
347	        }
348	        return date;
349	    }
350	
351	    /**
352	     * Find the existing owners that already belong to the same household as the given
353	     * last name and address, i.e. those sharing both fields. Both are compared
354	     * case-insensitively after collapsing runs of whitespace to a single space and
355	     * trimming the ends.
356	     */
357	    private List<Owner> findHouseholdMembers(String lastName, String address) {
358	        String normalizedLastName = normalizeForHousehold(lastName);
359	        String normalizedAddress = normalizeForHousehold(address);
360	        return this.clinicService.findAllOwners().stream()
361	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
362	                && normalizeForHousehold(existing.getAddress()).equals(normalizedAddress))
363	            .toList();
364	    }
365	
366	    /**
367	     * Find an existing owner that this new owner softly duplicates: one sharing the same
368	     * last name (compared case-insensitively after whitespace normalization) and the same
369	     * postcode, but with a different telephone. Returns the lowest-id such owner, or
370	     * {@code null} when the new owner has no postcode or no soft match exists. Owners
371	     * whose telephone equals the new owner's are excluded, as those are governed by the
372	     * hard-duplicate (identityKey) check rather than this soft match.
373	     */
374	    private Owner findPossibleDuplicate(Owner owner) {
375	        String postcode = owner.getPostcode();
376	        if (postcode == null) {
377	            return null;
378	        }
379	        String normalizedLastName = normalizeForHousehold(owner.getLastName());
380	        String telephone = owner.getTelephone();
381	        return this.clinicService.findAllOwners().stream()
382	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
383	                && postcode.equals(existing.getPostcode())
384	                && !java.util.Objects.equals(telephone, existing.getTelephone()))
385	            .min(java.util.Comparator.comparing(Owner::getId))
386	            .orElse(null);
387	    }
388	
389	    /**
390	     * Count the existing owners that already share both the given first and last
391	     * name, compared case-insensitively. Used to populate an owner's namesake count
392	     * at creation time, reflecting how many owners with the same name existed before
393	     * this one was created.
394	     */
395	    private int countNamesakes(String firstName, String lastName) {
396	        String normalizedFirstName = normalizeName(firstName);
397	        String normalizedLastName = normalizeName(lastName);
398	        return (int) this.clinicService.findAllOwners().stream()
399	            .filter(existing -> normalizeName(existing.getFirstName()).equals(normalizedFirstName)
400	                && normalizeName(existing.getLastName()).equals(normalizedLastName))
401	            .count();
402	    }
403	
404	    private String normalizeName(String value) {
405	        return value == null ? "" : value.toLowerCase(Locale.ROOT);
406	    }
407	
408	    /**
409	     * Build a stable identifier shared by all owners of one household. It is derived
410	     * deterministically from the normalized last name and address, so every owner at
411	     * the same household resolves to the same value regardless of creation order.
412	     */
413	    private String householdId(String lastName, String address) {
414	        String key = normalizeForHousehold(lastName) + "\n" + normalizeForHousehold(address);
415	        try {
416	            byte[] digest = MessageDigest.getInstance("SHA-256")
417	                .digest(key.getBytes(StandardCharsets.UTF_8));
418	            StringBuilder sb = new StringBuilder();
419	            for (int i = 0; i < 6; i++) {
420	                sb.append(String.format("%02X", digest[i]));
421	            }
422	            return "HH-" + sb;
423	        }
424	        catch (NoSuchAlgorithmException e) {
425	            throw new IllegalStateException(e);
426	        }
427	    }
428	
429	    private String normalizeForHousehold(String value) {
430	        if (value == null) {
431	            return "";
432	        }
433	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
434	    }
435	
436	    private String normalizeTelephone(String telephone) {
437	        if (telephone == null) {
438	            return null;
439	        }
440	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
441	        String digits;
442	        if (cleaned.startsWith("+")) {
443	            digits = cleaned.substring(1);
444	        } else {
445	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
446	            digits = "61" + national;
447	        }
448	        if (!digits.matches("[0-9]{8,15}")) {
449	            return null;
450	        }
451	        if (!hasValidNationalLength(digits)) {
452	            return null;
453	        }
454	        return "+" + digits;
455	    }
456	
457	    /**
458	     * Validate the national-number length of an E.164 number (the digits, without the
459	     * leading {@code '+'}) against its country code. Australia ({@code '+61'}) requires
460	     * exactly 9 national digits and North America ({@code '+1'}) exactly 10; country
461	     * codes without a known rule are accepted as-is.
462	     */
463	    private boolean hasValidNationalLength(String digits) {
464	        if (digits.startsWith("61")) {
465	            return digits.length() - 2 == 9;
466	        }
467	        if (digits.startsWith("1")) {
468	            return digits.length() - 1 == 10;
469	        }
470	        return true;
471	    }
472	
473	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
474	    @Override
475	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
476	        Owner owner = this.clinicService.findOwnerById(ownerId);
477	        if (owner != null) {
478	            Pet pet = owner.getPet(petId);
479	            if (pet != null) {
480	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
481	            }
482	        }
483	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
484	    }
485	}
