29	/**
30	 * Simple JavaBean domain object representing an owner.
31	 *
32	 * @author Ken Krebs
33	 * @author Juergen Hoeller
34	 * @author Sam Brannen
35	 * @author Michael Isvy
36	 */
37	@Entity
38	@Table(name = "owners")
39	public class Owner extends Person {
40	    @Column(name = "address")
41	    @NotEmpty
42	    private String address;
43	
44	    @Column(name = "city")
45	    @NotEmpty
46	    private String city;
47	
48	    @Column(name = "telephone")
49	    @NotEmpty
50	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (a '+' followed by 8 to 15 digits)")
51	    private String telephone;
52	
53	    @Column(name = "email")
54	    @Email
55	    private String email;
56	
57	    @Column(name = "registration_date")
58	    private LocalDate registrationDate;
59	
60	    @Column(name = "birth_date")
61	    private LocalDate birthDate;
62	
63	    @Column(name = "postcode")
64	    @Pattern(regexp = "^[0-9]{4}$", message = "Postcode must be 4 digits")
65	    private String postcode;
66	
67	    @Column(name = "customer_code")
68	    private String customerCode;
69	
70	    @Column(name = "household_id")
71	    private String householdId;
72	
73	    @Column(name = "namesake_count")
74	    private Integer namesakeCount;
75	
76	    @Column(name = "bulk_signup_warning")
77	    private Boolean bulkSignupWarning;
78	
79	    @Column(name = "household_size")
80	    private Integer householdSize;
81	
82	    @Column(name = "possible_duplicate")
83	    private Boolean possibleDuplicate;
84	
85	    @Column(name = "possible_duplicate_of")
86	    private Integer possibleDuplicateOf;
87	
88	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
89	    private Set<Pet> pets;
90	
91	    /** Common street-type abbreviations expanded during address normalization. */
92	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
93	        "ST", "STREET",
94	        "RD", "ROAD",
95	        "AVE", "AVENUE");
96	
97	    /** Fixed city-to-region table used to derive an owner's locality. */
98	    private static final Map<String, String> CITY_REGION = Map.of(
99	        "Sydney", "NSW",
100	        "Melbourne", "VIC",
101	        "Brisbane", "QLD");
102	
103	    /** Fixed region-to-postcode-range table (inclusive) used to validate a postcode. */
104	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
105	        "NSW", new int[] {2000, 2099},
106	        "VIC", new int[] {3000, 3099},
107	        "QLD", new int[] {4000, 4099});
108	
109	    public String getAddress() {
110	        return this.address;
111	    }
112	
113	    /**
114	     * Set the owner's address, normalizing it to a canonical form so it is both
115	     * stored and returned consistently. Leading/trailing whitespace is trimmed,
116	     * internal runs of whitespace are collapsed to a single space, the value is
117	     * upper-cased, and common street-type abbreviations are expanded ({@code ST ->
118	     * STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value is
119	     * left as-is.
120	     */
121	    public void setAddress(String address) {
122	        this.address = normalizeAddress(address);
123	    }
124	
125	    /**
126	     * Normalize an address string to its canonical form: trimmed, whitespace
127	     * collapsed, upper-cased, with common street-type abbreviations expanded.
128	     * Returns {@code null} for a {@code null} input; a value that is blank once
129	     * trimmed normalizes to the empty string.
130	     */
131	    public static String normalizeAddress(String address) {
132	        if (address == null) {
133	            return null;
134	        }
135	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
136	        if (collapsed.isEmpty()) {
137	            return "";
138	        }
139	        String[] tokens = collapsed.split(" ");
140	        StringBuilder sb = new StringBuilder();
141	        for (int i = 0; i < tokens.length; i++) {
142	            if (i > 0) {
143	                sb.append(' ');
144	            }
145	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
146	        }
147	        return sb.toString();
148	    }
149	
150	    public String getCity() {
151	        return this.city;
152	    }
153	
154	    public void setCity(String city) {
155	        this.city = city;
156	    }
157	
158	    public String getTelephone() {
159	        return this.telephone;
160	    }
161	
162	    public void setTelephone(String telephone) {
163	        this.telephone = telephone;
164	    }
165	
166	    public String getEmail() {
167	        return this.email;
168	    }
169	
170	    /**
171	     * Set the owner's email address, normalizing it to lower case so it is both
172	     * stored and returned in a canonical form. A {@code null} value is left as-is.
173	     */
174	    public void setEmail(String email) {
175	        this.email = (email == null) ? null : email.toLowerCase(Locale.ROOT);
176	    }
177	
178	    public LocalDate getRegistrationDate() {
179	        return this.registrationDate;
180	    }
181	
182	    public void setRegistrationDate(LocalDate registrationDate) {
183	        this.registrationDate = registrationDate;
184	    }
185	
186	    public LocalDate getBirthDate() {
187	        return this.birthDate;
188	    }
189	
190	    public void setBirthDate(LocalDate birthDate) {
191	        this.birthDate = birthDate;
192	    }
193	
194	    /**
195	     * Return the owner's age band derived from the birth date, computed against the
196	     * registration date: {@code 'MINOR'} when under 18, {@code 'ADULT'} when 18 to
197	     * 64 inclusive, and {@code 'SENIOR'} when 65 or older. Returns {@code null} when
198	     * either the birth date or the registration date is not set.
199	     */
200	    public String getAgeBand() {
201	        if (this.birthDate == null || this.registrationDate == null) {
202	            return null;
203	        }
204	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
205	        if (age < 18) {
206	            return "MINOR";
207	        }
208	        if (age < 65) {
209	            return "ADULT";
210	        }
211	        return "SENIOR";
212	    }
213	
214	    public String getPostcode() {
215	        return this.postcode;
216	    }
217	
218	    public void setPostcode(String postcode) {
219	        this.postcode = postcode;
220	    }
221	
222	    /**
223	     * Whether this owner's postcode is valid for its city. A {@code null} postcode
224	     * is always valid (postcode is optional). When present, a postcode is valid if
225	     * the city has no known region, or if it is four digits falling within the
226	     * inclusive range for the city's region ({@code Sydney -> NSW 2000-2099},
227	     * {@code Melbourne -> VIC 3000-3099}, {@code Brisbane -> QLD 4000-4099}).
228	     */
229	    public boolean isPostcodeValidForCity() {
230	        if (this.postcode == null) {
231	            return true;
232	        }
233	        String region = CITY_REGION.get(this.city);
234	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
235	        if (range == null) {
236	            return true;
